import functools
import json
import os
from pathlib import Path
import numpy as np

NAMES = ("allegro", "leap", "wuji", "inspire", "shadow", "svh", "ability", "dexhand021")
# Default: <repo>/hand_assets/normalized, generated by tools/fetch_hand_assets.py.
ASSETS = Path(
    os.environ.get("EGO2ROBOT_HAND_ASSETS", str(Path(__file__).resolve().parents[2] / "hand_assets/normalized"))
)


def selected():
    name = os.environ.get("EGO2ROBOT_END_EFFECTOR", "")
    if name not in NAMES:
        raise ValueError(f"Choose a registered end effector: {NAMES}; got {name!r}")
    return name


def profile(side, name=None):
    return _profile(side, name or selected())


@functools.lru_cache(None)
def _profile(side, name):
    p = json.loads((ASSETS / f"{name}_{side}.json").read_text())
    assert p["name"] == name and p["side"] == side
    _single_object_obj(p["normalized"])
    return p


def _single_object_obj(xml):
    """MuJoCo 3.11 compiles only the first object of a multi-object OBJ, silently dropping the rest of the
    mesh (LEAP fingertips, Shadow). Refuse such models instead of rendering a partial hand."""
    import xml.etree.ElementTree as E

    bad = []
    for me in E.parse(xml).getroot().iter("mesh"):
        f = me.get("file", "")
        if not f.lower().endswith(".obj"):
            continue
        f = Path(f) if Path(f).is_absolute() else Path(xml).parent / f
        objs = set()
        cur = "<none>"
        for line in open(f, errors="ignore"):
            if line.startswith(("o ", "g ")):
                cur = line.split(None, 1)[1].strip() if len(line.split()) > 1 else "<none>"
            elif line.startswith("f "):
                objs.add(cur)
        if len(objs) > 1:
            bad.append(str(f))
    if bad:
        raise ValueError(
            f"{xml}: multi-object OBJ meshes {bad}; use merged assets (EGO2ROBOT_HAND_ASSETS, see tools/fetch_hand_assets.py)"
        )


def affine(model, side):
    """Physical q = offset + M @ actual independent motor coordinates."""
    p = profile(side)
    names = p["joints"]
    motors = p["motor_names"]
    memo = {}

    def resolve(name, stack=()):
        if name in memo:
            return memo[name]
        if name in stack:
            raise ValueError("Cyclic coupling")
        if name not in p["mimic"]:
            row = np.zeros(len(motors))
            row[motors.index(name)] = 1.0
            result = (0.0, row)
        else:
            c = p["mimic"][name]
            offset, row = resolve(c["joint"], (*stack, name))
            result = (c["offset"] + c["multiplier"] * offset, c["multiplier"] * row)
        memo[name] = result
        return result

    resolved = [resolve(n) for n in names]
    adr = np.array([int(model.joint(f"{side}_hand_{n}").qposadr[0]) for n in names])
    return adr, np.array([x[0] for x in resolved]), np.array([x[1] for x in resolved])


def whole_affine(model, control=None):
    """Both arms and both hands, retaining physical state order in exports."""
    if control is None:
        control = np.arange(model.nq)
    control = np.asarray(control, dtype=int)
    lookup = {int(a): i for i, a in enumerate(control)}
    columns = []
    offset = np.zeros(len(control))
    names = []
    for side in ["left", "right"]:
        for i in range(1, 8):
            a = int(model.joint(f"{side}_joint{i}").qposadr[0])
            v = np.zeros(len(control))
            v[lookup[a]] = 1
            columns.append(v)
            names.append(f"{side}_joint{i}")
        adr, b, M = affine(model, side)
        offset[[lookup[int(a)] for a in adr]] = b
        for j, n in enumerate(profile(side)["motor_names"]):
            v = np.zeros(len(control))
            v[[lookup[int(a)] for a in adr]] = M[:, j]
            columns.append(v)
            names.append(f"{side}_hand_{n}")
    return offset, np.stack(columns, axis=1), names


def speed_limits(model, control=None):
    limits = np.full(model.nq, 3.0)
    for side in ["left", "right"]:
        p = profile(side)
        for name in p["joints"]:
            limits[int(model.joint(f"{side}_hand_{name}").qposadr[0])] = min(3.0, p["velocity_limits"].get(name, 3.0))
    return limits if control is None else limits[control]


def project_seed(model, q, times, fixed_rows=None):
    """Nearest trajectory satisfying all physical limits, speeds and coupling."""
    import clarabel
    from scipy import sparse

    q = np.asarray(q)
    speed_margin = np.diff(times)[:, None] * speed_limits(model)[None, :] - 1e-7
    # Preserve a feasible checkpoint exactly. An interior-point re-projection
    # can perturb it enough to cross a tight nonlinear TCP acceptance boundary.
    if (
        np.isfinite(q).all()
        and np.all(q >= model.jnt_range[:, 0])
        and np.all(q <= model.jnt_range[:, 1])
        and coupling_error(model, q) < 1e-10
        and np.all(abs(np.diff(q, axis=0)) <= speed_margin)
    ):
        return q.copy()
    b, M, names = whole_affine(model)
    n = len(q)
    C = sparse.kron(sparse.eye(n), sparse.csc_matrix(M), format="csc")
    offset = np.tile(b, n)
    D = sparse.kron(
        sparse.diags([-np.ones(n - 1), np.ones(n - 1)], [0, 1], shape=(n - 1, n)), sparse.eye(model.nq), format="csc"
    )
    caps = (np.diff(times)[:, None] * speed_limits(model)[None, :] - 1e-7).ravel()
    # Keep exact mechanism slopes: independently shrinking each slave bound
    # can empty the feasible set for vendor joints with extremely small ranges.
    lower = np.tile(model.jnt_range[:, 0], n)
    upper = np.tile(model.jnt_range[:, 1], n)
    for frame in fixed_rows or []:
        lower[frame * model.nq : (frame + 1) * model.nq] = q[frame]
        upper[frame * model.nq : (frame + 1) * model.nq] = q[frame]
    G = sparse.vstack([C, -C, D @ C, -D @ C], format="csc")
    h = np.r_[upper - offset, offset - lower, caps - D @ offset, caps + D @ offset]
    P = sparse.triu(C.T @ C, format="csc")
    linear = np.asarray(C.T @ (offset - q.ravel())).ravel()
    settings = clarabel.DefaultSettings()
    settings.verbose = False
    settings.max_iter = 500
    settings.tol_feas = 1e-9
    settings.tol_gap_abs = 1e-8
    solution = clarabel.DefaultSolver(P, linear, G, h, [clarabel.NonnegativeConeT(len(h))], settings).solve()
    if str(solution.status) not in ["Solved", "AlmostSolved"]:
        raise RuntimeError(f"Coupled seed projection: {solution.status}")
    return (offset + C @ np.asarray(solution.x)).reshape(q.shape)


def coupling_error(model, q):
    maximum = 0.0
    for side in ["left", "right"]:
        p = profile(side)
        for name, c in p["mimic"].items():
            a = int(model.joint(f"{side}_hand_{name}").qposadr[0])
            a2 = int(model.joint(f"{side}_hand_{c['joint']}").qposadr[0])
            maximum = max(maximum, float(np.max(abs(q[:, a] - c["offset"] - c["multiplier"] * q[:, a2]))))
    return maximum
